import java.io.*;
import java.util.*;

public class MainProgram {
    static BufferedReader reader;
    static PrintWriter writer;
    static long primeModulo = 1_000_000_000L + 7;

    public static void main(String[] args) throws Exception {
        StringBuilder buffer = new StringBuilder();
        if (buffer.length() == 0) {
            reader = new BufferedReader(new InputStreamReader(System.in));
        } else {
            reader = new BufferedReader(new StringReader(buffer.toString()));
        }
        writer = new PrintWriter(new OutputStreamWriter(System.out));
        setupData();
        executeSolution();
        writer.flush();
    }

    private static void setupData() {
        // Initialization logic not needed here
    }

    private static void executeSolution() throws IOException {
        int a = readInt();
        int b = readInt();
        int l = readInt() - 1;
        int r = readInt() - 1;
        int s = r - l + 1;

        for (char ch1 = 'a'; ch1 <= 'z'; ch1++)
            for (char ch2 = 'a'; ch2 <= 'z'; ch2++)
                for (char ch3 = 'a'; ch3 <= 'z'; ch3++)
                    s = Math.min(s, calculateOverlap(a, b, l, r, new char[]{ch1, ch2, ch3}));

        writer.println(s);
    }

    private static int calculateOverlap(int a, int b, int left, int right, char[] pattern) {
        char[] arr = new char[3 * (a + b)];
        for (int segmentIdx = 0; segmentIdx < 3; segmentIdx++) {
            System.arraycopy(generateDistinctChars(arr, segmentIdx * (a + b), a), 0, arr, segmentIdx * (a + b), a);
            Arrays.fill(arr, segmentIdx * (a + b) + a, (segmentIdx + 1) * (a + b), pattern[segmentIdx]);
        }

        int startOffset = left % (a + b);
        int totalLength = right - left + 1;
        arr = Arrays.copyOfRange(arr, startOffset, arr.length);
        arr = Arrays.copyOf(arr, Math.min(arr.length, totalLength));

        boolean[] observed = new boolean[26];
        for (char ch : arr) {
            observed[ch - 'a'] = true;
        }

        int totalTypes = 0;
        for (boolean flag : observed) {
            if (flag) totalTypes++;
        }
        return totalTypes;
    }

    private static char[] generateDistinctChars(char[] array, int index, int count) {
        boolean[] usedLetters = new boolean[26];
        for (int pos = index - 1; pos >= 0 && pos >= index - count; pos--) {
            usedLetters[array[pos] - 'a'] = true;
        }
        char[] result = new char[count];
        char c = 'a';
        int ptr = 0;
        while (ptr < count) {
            while (usedLetters[c - 'a']) c++;
            result[ptr++] = c++;
        }
        return result;
    }

    private static int readInt() throws IOException {
        return Integer.parseInt(reader.readLine().trim());
    }
}
